#!/usr/bin/env bash
#
# Documentation Post-render Script
# Removes the transient files generated by pre-render.sh.
#
# @license MIT License
# @copyright 2026 Mickaël Canouil
# @author Mickaël Canouil
#
# assets/social/og-image.png is left alone. It is ignored by Git like the two
# files below, but pre-render.sh caches it rather than generating it, and a
# render with no network reuses whatever is there.
#

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
DOCS_DIR="$(dirname "${SCRIPT_DIR}")"

rm -f "${DOCS_DIR}/changelog.qmd"
removed="changelog.qmd"

# _variables.yml is removed only when a script generated it, so a hand-written
# one in a repository that generates none is left alone.
if head -n 1 "${DOCS_DIR}/_variables.yml" 2>/dev/null | grep -q '^# Generated by'; then
	rm -f "${DOCS_DIR}/_variables.yml"
	removed="${removed} and _variables.yml"
fi
printf '[post-render] Removed %s\n' "${removed}"
